/**
 * Drag and drop con SortableJS - listas anidadas.
 * Banco del sistema: solo se permite soltar dentro de la misma rama (curso).
 * Varios cursos en la misma página: solo dentro del mismo bloque .course-block.
 *
 * @module     local_dragndrop/dragndrop
 * @copyright  2025
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

define(['jquery'], function($) {
    'use strict';

    var ajaxUrl = '';
    var sessKey = '';

    /**
     * Lista destino: rama requerida ('TOP' = hijos directos del tope) o id de categoría curso.
     *
     * @param {Element} listEl
     * @return {string|null}
     */
    function getRequiredBranchForList(listEl) {
        var p = listEl.parentElement;
        while (p) {
            if (p.classList && p.classList.contains('course-block')) {
                break;
            }
            if (p.classList && p.classList.contains('sortable-item')) {
                return p.getAttribute('data-categoryid');
            }
            p = p.parentElement;
        }
        return 'TOP';
    }

    /**
     * ¿Se admite soltar el elemento en esta lista?
     *
     * @param {Element} listEl
     * @param {Element} dragEl
     * @return {boolean}
     */
    function canDropInSystemBank(listEl, dragEl) {
        var req = getRequiredBranchForList(listEl);
        var dragBranch = dragEl.getAttribute('data-branchroot');
        var dragCat = dragEl.getAttribute('data-categoryid');
        if (req === 'TOP') {
            return dragBranch === dragCat;
        }
        return dragBranch === req;
    }

    /**
     * Mismo bloque curso (vista multicurso o curso único fuera del banco sistema).
     *
     * @param {Element} toList
     * @param {Element} dragEl
     * @return {boolean}
     */
    function canDropInCourseBlock(toList, dragEl) {
        var toBlock = toList.closest('.course-block');
        var fromBlock = dragEl.closest('.course-block');
        return toBlock && fromBlock && toBlock === fromBlock;
    }

    /**
     * Inicializa Sortable en todas las listas del plugin.
     *
     * @param {string} url URL de ajax.php
     * @param {string} sesskey Clave de sesión
     */
    function init(url, sesskey) {
        ajaxUrl = url;
        sessKey = sesskey;

        $(document).ready(function() {
            var Sortable = window.Sortable;
            if (!Sortable) {
                return;
            }

            var nestedSortables = document.querySelectorAll('.course-block ul.dragndrop-categories');
            for (var i = 0; i < nestedSortables.length; i++) {
                new Sortable(nestedSortables[i], {
                    group: 'nested',
                    animation: 150,
                    fallbackOnBody: true,
                    swapThreshold: 0.65,
                    handle: '.handle-icon',
                    draggable: 'li.sortable-item',
                    onMove: function(evt) {
                        var block = evt.to.closest('.course-block');
                        if (!block) {
                            return false;
                        }
                        if (block.getAttribute('data-system-bank') === '1') {
                            return canDropInSystemBank(evt.to, evt.dragged);
                        }
                        return canDropInCourseBlock(evt.to, evt.dragged);
                    },
                    onEnd: function(evt) {
                        var item = evt.item;
                        var newParent = evt.to;
                        var newIndex = evt.newIndex;
                        var catId = parseInt(item.getAttribute('data-categoryid'), 10);
                        var parentId = getParentId(newParent);
                        saveMove(catId, parentId, newIndex, function() {
                            $(newParent).removeClass('sortable-list-empty');
                            if (evt.from && evt.from.children.length === 0) {
                                $(evt.from).addClass('sortable-list-empty');
                            }
                        }, function() {
                            window.location.reload();
                        });
                    }
                });
            }
        });
    }

    /**
     * Resuelve el id del padre en base a la lista destino.
     *
     * @param {Element} listEl Elemento UL sortable
     * @return {number}
     */
    function getParentId(listEl) {
        var parentItem = listEl.closest('li.sortable-item');
        if (parentItem) {
            return parseInt(parentItem.getAttribute('data-categoryid'), 10);
        }
        var block = listEl.closest('.course-block');
        var topId = block ? block.getAttribute('data-topcategoryid') : null;
        return topId ? parseInt(topId, 10) : 0;
    }

    /**
     * Persiste parent y orden por AJAX.
     *
     * @param {number} categoryId
     * @param {number} newParent
     * @param {number} sortorder
     * @param {Function} onSuccess
     * @param {Function} onError
     */
    function saveMove(categoryId, newParent, sortorder, onSuccess, onError) {
        $.ajax({
            url: ajaxUrl,
            type: 'POST',
            cache: false,
            data: {
                sesskey: sessKey,
                action: 'move',
                categoryid: categoryId,
                newparent: newParent,
                sortorder: sortorder
            },
            dataType: 'json'
        }).done(function(response) {
            if (response && response.success === true) {
                onSuccess();
            } else {
                onError();
            }
        }).fail(function() {
            onError();
        });
    }

    return { init: init };
});
